const tbl=(h,rows)=>'<table><tr>'+h.map(x=>`<th>${x}</th>`).join('')+'</tr>'+rows.map(r=>'<tr>'+r.map(x=>`<td>${x||'<br>'}</td>`).join('')+'</tr>').join('')+'</table>';
