/* ---------- note ops ---------- */
function newNote(o){o=o||{};const t=Date.now(),n={id:uid(),title:o.title||'',html:o.html||'',nb:o.nb||(ui.view.startsWith('nb:')?ui.view.slice(3):null),tags:o.tags||(ui.view.startsWith('tag:')?[ui.view.slice(4)]:[]),pin:false,color:'',created:t,updated:t,trash:false,client:o.client?{name:'',dob:'',tob:'',pob:'',open:true}:null,ver:[]};S.notes.unshift(n);persist();return n;}
function openNote(id){ui.sel=id;ui.view=ui.view==='home'?'all':ui.view;$('#app').classList.add('edit');render();}
function snap(n){const last=n.ver[0];if(last&&Date.now()-last.t<120000)return;if(last&&last.h===n.html&&last.ti===n.title)return;n.ver.unshift({t:Date.now(),h:n.html,ti:n.title});n.ver=n.ver.slice(0,10);}
function matches(n,q){if(!q)return null;const t=(n.title+' '+txt(n.html)+' '+n.tags.join(' ')+' '+(n.client?n.client.name:'')).toLowerCase(),ws=q.toLowerCase().split(/\s+/).filter(Boolean);return ws.every(w=>t.includes(w));}
function listFor(){let a=ui.view==='trash'?S.notes.filter(n=>n.trash):live();const v=ui.view;if(v==='pinned')a=a.filter(n=>n.pin);else if(v.startsWith('nb:'))a=a.filter(n=>n.nb===v.slice(3));else if(v.startsWith('tag:'))a=a.filter(n=>n.tags.includes(v.slice(4)));
 if(ui.filt==='client')a=a.filter(n=>n.client);else if(ui.filt==='tasks')a=a.filter(n=>/class="cl"/.test(n.html));
 if(ui.q)a=a.filter(n=>matches(n,ui.q));
 const s=ui.sort;a=a.slice().sort((x,y)=>(y.pin-x.pin)||(s==='title'?(x.title||'~').localeCompare(y.title||'~'):s==='created'?y.created-x.created:y.updated-x.updated));return a;}
/* ---------- render ---------- */
function applyTheme(){document.documentElement.dataset.theme=S.set.theme==='dark'?'':S.set.theme;document.documentElement.dataset.acc=S.set.acc==='gold'?'':S.set.acc;document.documentElement.style.setProperty('--fs',S.set.fs+'px');}
function tasksAll(){const o=[];live().forEach(n=>{const d=document.createElement('div');d.innerHTML=n.html;d.querySelectorAll('ul.cl li').forEach((li,i)=>o.push({n,i,t:li.textContent.trim(),done:li.classList.contains('done')}));});return o.filter(x=>x.t);}
function renderNav(){const L=live(),tags={};L.forEach(n=>n.tags.forEach(t=>tags[t]=(tags[t]||0)+1));const tk=tasksAll().filter(t=>!t.done).length,pe=S.preds.filter(x=>x.st==='pending').length;
 const it=(v,e,l,c)=>`<button class="nv${ui.view===v?' on':''}" data-v="${esc(v)}"><span class="e">${e}</span>${esc(l)}${c!=null?`<span class="n">${c}</span>`:''}</button>`;
 $('#nav').innerHTML=it('home','🏛️','Home')+it('all','🗒️','All notes',L.length)+it('pinned','📌','Pinned',L.filter(n=>n.pin).length)+it('tasks','✅','Tasks',tk)+it('pred','🎯','Predictions',pe)+
 `<div class="nh">Notebooks<button data-a="addnb" title="New notebook">＋</button></div>`+S.nbs.map(b=>it('nb:'+b.id,b.ic,b.name,L.filter(n=>n.nb===b.id).length)).join('')+
 (Object.keys(tags).length?`<div class="nh">Tags</div>`+Object.keys(tags).sort().map(t=>it('tag:'+t,'#',t,tags[t])).join(''):'')+
 `<div class="nh">System</div>`+it('trash','🗑️','Trash',S.notes.filter(n=>n.trash).length);}
function renderList(){const titles={home:'Home',all:'All notes',pinned:'Pinned',trash:'Trash',tasks:'Tasks',pred:'Predictions'};let t=titles[ui.view];if(!t){if(ui.view.startsWith('nb:')){const b=S.nbs.find(x=>x.id===ui.view.slice(3));t=b?b.ic+' '+b.name:'Notebook';}else t='#'+ui.view.slice(4);}
 const a=(ui.view==='home'||ui.view==='tasks'||ui.view==='pred')?live():listFor();const base=(ui.view==='home'||ui.view==='tasks'||ui.view==='pred')?listForAll():a;
 $('#lTitle').innerHTML=esc(t)+` <small>${base.length} note${base.length===1?'':'s'}</small>`;
 $('#lChips').innerHTML=[['all','All'],['client','👤 Clients'],['tasks','✅ With tasks']].map(c=>`<button class="chip${ui.filt===c[0]?' on':''}" data-f="${c[0]}">${c[1]}</button>`).join('')+`<button class="chip" data-a="sort" style="margin-left:auto">⇅ ${ui.sort==='updated'?'Recent':ui.sort==='created'?'Created':'A–Z'}</button>`;
 $('#items').innerHTML=base.length?base.map((n,i)=>{const pr=txt(n.html);let sn=pr.slice(0,140);if(ui.q){const k=ui.q.toLowerCase().split(/\s+/)[0],ix=pr.toLowerCase().indexOf(k);if(ix>40)sn='…'+pr.slice(ix-30,ix+110);}
  const nb=S.nbs.find(b=>b.id===n.nb);return `<button class="it${ui.sel===n.id?' on':''}" data-id="${n.id}" style="--cc:${n.color||'transparent'};animation-delay:${Math.min(i,10)*18}ms"><b>${n.pin?'<em style="font-style:normal">📌</em>':''}<span>${hl(n.title||'Untitled',ui.q)}</span></b><p>${hl(sn||'No content yet',ui.q)}</p><div class="mt">${n.client&&n.client.name?`<span>👤 ${esc(n.client.name)}</span>`:''}${nb?`<span>${nb.ic} ${esc(nb.name)}</span>`:''}${n.tags.slice(0,3).map(x=>`<span class="tg">${esc(x)}</span>`).join('')}<span style="margin-left:auto">${rel(n.updated)}</span></div></button>`;}).join('')
  :`<div class="empty"><div class="big">${ui.q?'🔍':ui.view==='trash'?'🗑️':'🪔'}</div>${ui.q?'No notes match your search.':ui.view==='trash'?'Trash is empty.':'Nothing here yet.<br>Press <b>＋ New note</b> or pick a template.'}</div>`;}
function listForAll(){const v=ui.view;ui.view='all';const r=listFor();ui.view=v;return r;}
function renderMain(){const mb=$('#mainBody');if(ui.view==='tasks')return mb.innerHTML=tasksHTML();if(ui.view==='pred')return mb.innerHTML=predHTML();
 const n=ui.sel&&N(ui.sel);if(!n||(n.trash&&ui.view!=='trash')){ui.sel=null;if(ui.view==='trash'||ui.view==='home'||true)return mb.innerHTML=ui.view==='home'?homeHTML():`<div class="home"><div class="empty"><div class="big">🪔</div>Select a note on the left, or create a new one.<div style="margin-top:14px"><button class="btn p" data-a="new">＋ New note</button></div></div></div>`;}
 editorHTML(n);}
