function homeHTML(){const d=new Date(),dy=DAYS[d.getDay()],L=live(),pe=S.preds,res=pe.filter(x=>x.st!=='pending'),hits=res.reduce((a,x)=>a+(x.st==='hit'?1:x.st==='partial'?.5:0),0),tk=tasksAll(),h=d.getHours(),gr=h<5?'Still up':h<12?'Good morning':h<17?'Good afternoon':'Good evening',g=GR.find(x=>x[0]===dy[1]);
 const due=pe.filter(x=>x.st==='pending'&&x.target&&x.target<=todayISO()).length;
 const rec=L.slice().sort((a,b)=>b.updated-a.updated).slice(0,6);
 return `<div class="home"><div class="hin"><div class="hero" data-g="${g[1]}"><small>${esc(fdate(d))}</small><h1>${gr}, ${dy[0]} belongs to ${dy[2]} ${g[1]}</h1><p>${esc(dy[4])}. A good day to ${dy[1]==='Mercury'?'write, study and sign':dy[1]==='Saturn'?'finish pending work and serve':dy[1]==='Jupiter'?'teach, counsel and plan':dy[1]==='Venus'?'create and connect':dy[1]==='Mars'?'act and decide':dy[1]==='Moon'?'reflect and care':'lead and recharge'}.</p><div class="sw"><span>Colour: ${esc(dy[3])}</span><span>Ruler: ${esc(dy[1])}</span></div></div>
 <div class="qa"><button class="qb" data-a="new"><span class="e">📝</span><b>New note</b><small>Start writing</small></button><button class="qb" data-a="tpl"><span class="e">🗂️</span><b>From template</b><small>Consultation, Prashna, Muhurta…</small></button><button class="qb" data-a="client"><span class="e">👤</span><b>New client case</b><small>Birth data + session notes</small></button><button class="qb" data-a="addpred"><span class="e">🎯</span><b>Log a prediction</b><small>Track your accuracy</small></button></div>
 <div class="stats"><div class="st"><b>${L.length}</b><small>notes</small></div><div class="st"><b>${L.filter(n=>n.client).length}</b><small>client cases</small></div><div class="st"><b>${tk.filter(t=>!t.done).length}</b><small>open tasks</small></div><div class="st"><b>${res.length?Math.round(hits/res.length*100)+'%':'—'}</b><small>prediction accuracy</small></div>${due?`<div class="st"><b style="color:var(--warn)">${due}</b><small>predictions to review</small></div>`:''}</div>
 <div class="sec">Recent notes</div><div class="rec">${rec.length?rec.map(n=>`<button class="it" data-id="${n.id}" style="--cc:${n.color||'transparent'};border-color:var(--line);background:var(--panel)"><b><span>${esc(n.title||'Untitled')}</span></b><p>${esc(txt(n.html).slice(0,100)||'Empty note')}</p><div class="mt"><span style="margin-left:auto">${rel(n.updated)}</span></div></button>`).join(''):'<div class="empty" style="grid-column:1/-1">No notes yet — create your first one.</div>'}</div>
 <div class="sec">Shortcuts</div><div class="hint">Ctrl+K command palette · Ctrl+N new note · / search · Ctrl+B/I/U formatting · Ctrl+Shift+P astro palette · Ctrl+S save now · Esc close</div></div></div>`;}
