 const cd=T.closest('[data-col]');if(cd){const n=N(ui.sel);n.color=cd.dataset.col;persist();$$('.cd').forEach(x=>x.classList.toggle('on',x.dataset.col===n.color));renderList();return;}
 const tp=T.closest('[data-tpl]');if(tp){useTpl(tp.dataset.tpl);return;}
